from scipy.optimize import least_squares
t,x,v,y=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
cands={
 'logv': lambda p: p[5]*np.log(v),
 'sqrtt*logv': lambda p: p[5]*np.sqrt(t)*np.log(v),
 'v3': lambda p: p[5]*v**3,
 'expv': lambda p: p[5]*np.exp(p[6]*v),
 'sinxv': lambda p: p[5]*np.sin(p[6]*x)*v,
}
def mk(name):
    def m(p):
        a,b,c,d,e=p[:5]
        return a*v**2 + b*np.log(1+c*x)*t + d*np.exp(-e*t**2)*v + cands[name](p)
    return m
for name in cands:
    best=None
    for s in range(40):
        p0=np.random.RandomState(s).uniform(-2,2,7)
        try:
            r=least_squares(lambda p: mk(name)(p)-y, p0, max_nfev=2000)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    print(name, np.mean(best.fun**2)/np.var(y), np.round(best.x,4))

